input.sparql:
SELECT ?s ?ref ?tid WHERE {
  ?s ref:hasLabel "Perimeter_mid_ZN_3" .
  OPTIONAL { ?s ref:hasExternalReference ?ref . ?ref ref:hasTimeseriesId ?tid }
}

SELECT ?p ?pname ?tid WHERE {
  ?p brick:isPartOf/brick:hasLocation ?z .
  FILTER(?z = <http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z02>)
  OPTIONAL { ?p ref:hasExternalReference ?ref . ?ref ref:hasTimeseriesId ?tid }
  ?p brick:hasLabel ?pname .
}

SELECT ?p ?tid WHERE {
  ?p <http://brickschema.org/schema/1.2/Brick#isPartOf> <http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z02> .
  OPTIONAL { ?p ref:hasExternalReference ?ref . ?ref ref:hasTimeseriesId ?tid }
  FILTER(?tid != "http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z02")
}

SELECT ?o ?rel ?pname WHERE {
  <http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z02> ?rel ?o .
  FILTER(?rel != <http://www.w3.org/1999/02/22-rdf-syntax-ns#type>)
  OPTIONAL { ?o brick:hasLabel ?pname }
}
LIMIT 100
